Method.Implementation:
	 try{
		do ##super()
		$$$TRACE("Connect to " _ ..ApplicationAddress)
		set ..objCdrTuxService = ##class(org.ihc.itf.cdr.mmi.CheckMmi).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService, ..LogDirectory _"/" _$$$JobConfigName _".log", $$$ConfigTrace($$$JobConfigName))
     	set status = ..CheckObject()
	}catch err{
		$$$LOGERROR("Exception while Creating Tuxedo Service: " _err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
	    set status=$$$ERROR(" Exception while initializing Tuxedo Service: "_err.AsSystemError()_"::"_err.Data_"::"_err.Code)
	}

	quit status

	 #dim status as %Status
	 set status = $$$OK
	 $$$TRACE("Inside IHC.ITF.ITFCOMMON.CDR.OpCheckMmi OnMessage method <"_pRequest.StringValue_">")	 


	 try {	
	 	if (..CheckObject() '= $$$OK) {
		 	$$$TRACE("**** Object does not exists ****")
		 	// Try to re intialize
		 	set result = ..OnInit()
			if (result '= $$$OK)
			{
				set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Op-Cdr-CHECKMMI", "CheckMMI failed. MMI#: " _pRequest.StringValue_ " ; Reason: " _ result)						
				return status
			}
	 	}

		$$$TRACE("Object name: " _ ..objCdrTuxService.%ClassName(1))

		set result = ..objCdrTuxService.checkMmi(pRequest.StringValue)		
		set pResponse = ##class(Ens.StringResponse).%New()  
 		set pResponse.StringValue = result 
 		$$$TRACE("**** After CheckMMi Call ****"_pResponse.StringValue)	

 		if ("1" = result){
	 		 	$$$TRACE("MMI# exists in CDR: "_pRequest.StringValue)
 		}else{ 		
 				if ("0" = result){
	 			 $$$TRACE("MMI# NOT exists in CDR: "_pRequest.StringValue)
 				}else{
	 		     set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Op-Cdr-CHECKMMI", "CheckMMI failed. MMI#: " _pRequest.StringValue_ " ; Reason: " _ result)						
	 			}
 		}
 		$$$TRACE("Result: " _ 	pRequest.StringValue _ ": " _ result)


	 } catch err {	
		    Set status = ..ExceptionHandler(err, "OnMessage")
	 }	    

	 $$$TRACE("OnMessage status: " _ status)	
	 return status
